from shop import pricing
from shop.cart import Cart


def main(argv):
    cart = Cart()
    for arg in argv:
        price, qty = arg.split("x")
        cart.add(float(price), int(qty))
    print(pricing.compute_total(cart.items))
    return cart.checkout()
```

